import { isHiddenSource, isCyberRelated } from "@/lib/feed-filters";

// Sources to drop server-side from CISO queries — must match the patterns
// in feed-filters.ts. Postgres `IN` list of exact and partial source names
// that flood the dashboard with low-signal items.
const CISO_EXCLUDED = '("OpenPhish","OpenPhish Feed","PhishTank Stats","PhishTank","Vulners News","VulDB","VulDB Recent","MalwareBazaar Recent","MalwareBazaar","NVD / NIST","NVD","NIST","GitHub Advisories","GitHub Security Advisories","GHSA")';
const isCisoExcluded = (s?: string | null) => isHiddenSource(s) ||
  ["openphish","phishtank","vulners","vuldb","malwarebazaar","nvd","nist","ghsa","github advisor","github security"].some(p =>
    (s || "").toLowerCase().includes(p),
  );

