// ─── Helpers ──────────────────────────────────────────────────────────────────

function todayISO(): string {
  const d = new Date();
  d.setHours(0, 0, 0, 0);
  return d.toISOString();
}

function formatDate(iso: string): string {
  return new Date(iso).toLocaleTimeString("en-US", {
    hour: "2-digit",
    minute: "2-digit",
    hour12: true,
  });
}

function riskLevel(critical: number): string {
  if (critical >= 10) return "CRITICAL";
  if (critical >= 5) return "HIGH";
  if (critical >= 1) return "MEDIUM";
  return "LOW";
}

function riskBadgeColor(level: string): string {
  const map: Record<string, string> = {
    CRITICAL: "bg-red-600 text-white",
    HIGH: "bg-orange-500 text-white",
    MEDIUM: "bg-blue-500 text-white",
    LOW: "bg-green-600 text-white",
  };
  return map[level] ?? "bg-slate-600 text-white";
}

function severityBadgeColor(severity: string): string {
  const map: Record<string, string> = {
    critical: "bg-red-600/20 text-red-400 border border-red-500/30",
    high: "bg-orange-600/20 text-orange-400 border border-orange-500/30",
    medium: "bg-blue-600/20 text-blue-400 border border-blue-500/30",
    low: "bg-green-600/20 text-green-400 border border-green-500/30",
  };
  return map[severity] ?? "bg-slate-600/20 text-slate-400 border border-slate-500/30";
}

// ─── Brief Parsing ────────────────────────────────────────────────────────────

function parseBrief(raw: string): BriefSection[] {
  const knownHeaders = [
    "THREAT LANDSCAPE OVERVIEW",
    "TOP THREATS TODAY",
    "INDUSTRIES AT RISK",
    "RISK LEVEL",
    "KEY METRICS",
    "RECOMMENDED EXECUTIVE ACTIONS",
    "OUTLOOK",
  ];

  // Build regex that splits on any known all-caps header (optionally with colon/hash prefix)
  const headerPattern = new RegExp(
    `(?:^|\\n)\\s*(?:#+\\s*)?\\*{0,2}(${knownHeaders.map((h) => h.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")).join("|")})\\*{0,2}:?\\s*`,
    "gi"
  );

  const sections: BriefSection[] = [];
  let lastHeader = "";
  let lastIndex = 0;
  let match: RegExpExecArray | null;

  const cleaned = raw.replace(/\r\n/g, "\n");

  while ((match = headerPattern.exec(cleaned)) !== null) {
    if (lastHeader) {
      sections.push({
        header: lastHeader,
        body: cleaned.slice(lastIndex, match.index).trim(),
      });
    }
    lastHeader = match[1].toUpperCase();
    lastIndex = match.index + match[0].length;
  }

  if (lastHeader) {
    sections.push({ header: lastHeader, body: cleaned.slice(lastIndex).trim() });
  }

  // Fallback: return raw text as a single section
  if (sections.length === 0) {
    sections.push({ header: "EXECUTIVE BRIEF", body: cleaned.trim() });
  }

  return sections;
}

// ─── Groq Call ────────────────────────────────────────────────────────────────

async function callGroq(prompt: string, apiKey: string): Promise<string> {
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), 30000);
  try {
    const res = await fetch("https://api.groq.com/openai/v1/chat/completions", {
      method: "POST",
      signal: ctrl.signal,
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${apiKey}`,
      },
      body: JSON.stringify({
        model: "llama-3.3-70b-versatile",
        max_tokens: 1800,
        temperature: 0.3,
        messages: [{ role: "user", content: prompt }],
      }),
    });
    clearTimeout(timer);
    if (!res.ok) {
      const err = await res.text().catch(() => "");
      throw new Error(`Groq ${res.status}: ${err.slice(0, 120)}`);
    }
    const json = await res.json();
    const text = (json.choices?.[0]?.message?.content ?? "").trim();
    if (text.length < 100) throw new Error("Groq returned an empty response");
    return text;
  } catch (e) {
    clearTimeout(timer);
    throw e;
  }
}

// ─── Prompt Builder ───────────────────────────────────────────────────────────

function buildPrompt(data: BriefData, dateStr: string): string {
  const criticalList = data.recentCritical
    .map((t, i) => `${i + 1}. "${t.title}" — ${t.excerpt ?? "No excerpt available."}`)
    .join("\n");

  const categoryList = data.topCategories
    .map((c) => `• ${c.name} (${c.count} threats)`)
    .join("\n");

  return `You are a senior cybersecurity advisor preparing a confidential daily brief for the CEO, Board of Directors, and C-Suite. Today is ${dateStr}.

THREAT DATA SUMMARY:
- Total new threats detected today: ${data.totalToday}
- Critical severity: ${data.critical}
- High severity: ${data.high}
- Medium severity: ${data.medium}
- Low severity: ${data.low}

TOP CRITICAL THREATS:
${criticalList || "No critical threats today."}

TOP THREAT CATEGORIES:
${categoryList || "No category data available."}

Generate a structured EXECUTIVE BRIEF with EXACTLY these section headers (all caps, on their own line):

THREAT LANDSCAPE OVERVIEW
Write 2-3 non-technical sentences summarizing today's threat environment for a board-level audience. Avoid jargon.

TOP THREATS TODAY
List the 3-5 most significant named threats. For each, provide: the threat name, what it does in plain English, and its potential business impact.

INDUSTRIES AT RISK
List the industries and sectors most at risk based on today's threats.

RISK LEVEL
State one word only: CRITICAL, HIGH, MEDIUM, or LOW — reflecting today's overall organizational risk posture.

KEY METRICS
Bullet list of today's key numbers (threat counts, severity breakdown, category highlights).

RECOMMENDED EXECUTIVE ACTIONS
3-4 numbered, actionable steps for executive leadership. Use boardroom language (risk mitigation, resource allocation, stakeholder communication).

OUTLOOK
One sentence describing what leadership should watch for in the next 24-48 hours.

Write in professional, boardroom-appropriate language. No technical jargon. No markdown code blocks. Use plain text with the section headers exactly as specified above.`;
}

// ─── Fallback Brief ───────────────────────────────────────────────────────────

function buildFallbackBrief(data: BriefData, dateStr: string): string {
  const risk = riskLevel(data.critical);
  const topCat = data.topCategories[0]?.name ?? "various categories";
  const criticalTitles = data.recentCritical.map((t) => `• ${t.title}`).join("\n") || "• No critical threats detected today.";

  return `THREAT LANDSCAPE OVERVIEW
Today, ${dateStr}, the organization's threat monitoring systems detected ${data.totalToday} new security threats. Of these, ${data.critical} are classified as critical severity, requiring immediate leadership awareness. The threat environment remains active across ${topCat} and related domains.

TOP THREATS TODAY
${criticalTitles}

INDUSTRIES AT RISK
Based on today's threat intelligence, organizations in financial services, healthcare, critical infrastructure, and technology sectors face elevated exposure. Supply chain and government entities may also be targeted.

RISK LEVEL
${risk}

KEY METRICS
• Total threats detected today: ${data.totalToday}
• Critical severity: ${data.critical}
• High severity: ${data.high}
• Medium severity: ${data.medium}
• Low severity: ${data.low}
• Top category: ${data.topCategories[0]?.name ?? "N/A"} (${data.topCategories[0]?.count ?? 0} threats)

RECOMMENDED EXECUTIVE ACTIONS
1. Ensure security operations teams are actively monitoring and triaging the ${data.critical} critical alerts identified today.
2. Brief department heads on the elevated risk posture and instruct them to verify business continuity readiness.
3. Review vendor and third-party access privileges in light of today's threat categories.
4. Schedule an executive security review if the critical threat count remains elevated over the next 24 hours.

OUTLOOK
Leadership should monitor for escalation in ${topCat}-related threats and ensure incident response plans are current and accessible to all relevant stakeholders.`;
}

// ─── Main Component ───────────────────────────────────────────────────────────

export default function CISOBrief() {
  const { toast } = useToast();

  const [loading, setLoading] = useState(true);
  const [generating, setGenerating] = useState(false);
  const [emailing, setEmailing] = useState(false);

  const [briefData, setBriefData] = useState<BriefData | null>(null);
  const [rawBrief, setRawBrief] = useState<string>("");
  const [parsedSections, setParsedSections] = useState<BriefSection[]>([]);

  const today = new Date();
  const dateStr = today.toLocaleDateString("en-US", {
    weekday: "long",
    year: "numeric",
    month: "long",
    day: "numeric",
  });

  // ── Data Fetching ──────────────────────────────────────────────────────────

  async function fetchData() {
    setLoading(true);
    try {
      // Wider lookback: 7 days. "Today only" leaves the page empty at 9 AM
      // when no critical/high feeds have landed yet, and analysts expect to
      // see the rolling week's leadership-relevant activity here.
      const startOfDay = todayISO();
      const since7d    = new Date(Date.now() - 7 * 86_400_000).toISOString();

      const [todayAll, criticalItems, allSeverity, categoryRows, latestRows] = await Promise.all([
        // Count today's threats (kept for the dashboard tile)
        supabase
          .from("threat_items")
          .select("id", { count: "exact", head: true })
          .gte("created_at", startOfDay),

        // Top 12 critical items in the last 7 days — was 5, was today-only.
        supabase
          .from("threat_items")
          .select("id, title, severity, category, source_name, excerpt, published_at")
          .eq("severity", "critical")
          .not("source_name", "in", CISO_EXCLUDED)
          .gte("created_at", since7d)
          .order("published_at", { ascending: false })
          .limit(12),

        // Severity breakdown for the past 7 days so counts aren't all zero
        // at the start of a quiet day.
        supabase
          .from("threat_items")
          .select("severity")
          .not("source_name", "in", CISO_EXCLUDED)
          .gte("created_at", since7d),

        // Category counts — last 7 days
        supabase
          .from("threat_items")
          .select("category")
          .not("source_name", "in", CISO_EXCLUDED)
          .gte("created_at", since7d)
          .limit(2000),

        // Latest 25 items (was 10) — critical + high + malware over 7 days.
        supabase
          .from("threat_items")
          .select("id, title, severity, category, source_name, excerpt, published_at")
          .not("source_name", "in", CISO_EXCLUDED)
          .or("severity.in.(critical,high),category.eq.malware,category.eq.ransomware,category.eq.breach")
          .gte("created_at", since7d)
          .order("published_at", { ascending: false })
          .limit(25),
      ]);

      // Severity counts
      const sevCounts: Record<string, number> = { critical: 0, high: 0, medium: 0, low: 0 };
      (allSeverity.data ?? []).forEach((r: { severity: string }) => {
        if (sevCounts[r.severity] !== undefined) sevCounts[r.severity]++;
      });

      // Category counts
      const catMap: Record<string, number> = {};
      (categoryRows.data ?? []).forEach((r: { category: string }) => {
        catMap[r.category] = (catMap[r.category] ?? 0) + 1;
      });
      const topCategories = Object.entries(catMap)
        .sort((a, b) => b[1] - a[1])
        .slice(0, 5)
        .map(([name, count]) => ({ name, count }));

      // Belt-and-suspenders: server-side IN-list already strips most noise,
      // but `isCyberRelated` + `isCisoExcluded` filter out anything that
      // sneaks through (e.g. category-tagged off-topic content, or sources
      // whose name varies slightly from the IN-list).
      const cleanList = (rows: ThreatItem[]) =>
        rows.filter((i) =>
          !isCisoExcluded(i.source_name) &&
          isCyberRelated({
            title: i.title, excerpt: i.excerpt ?? "", source_name: i.source_name ?? "", category: i.category ?? "",
          } as any),
        );

      setBriefData({
        totalToday: todayAll.count ?? 0,
        critical: sevCounts.critical,
        high: sevCounts.high,
        medium: sevCounts.medium,
        low: sevCounts.low,
        topCategories,
        recentCritical: cleanList((criticalItems.data ?? []) as ThreatItem[]),
        latestItems:    cleanList((latestRows.data    ?? []) as ThreatItem[]),
      });
    } catch (err) {
      console.error("Failed to fetch brief data:", err);
      toast({
        title: "Data fetch failed",
        description: "Could not load threat data. Please try again.",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    fetchData();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // ── Brief Generation ───────────────────────────────────────────────────────

  async function generateBrief() {
    if (!briefData) return;
    setGenerating(true);
    try {
      const apiKey = import.meta.env.VITE_GROQ_API_KEY as string | undefined;
      let text: string;
      let usedAI = false;

      if (apiKey && apiKey.trim().length > 10 && apiKey.trim() !== "undefined") {
        const prompt = buildPrompt(briefData, dateStr);
        try {
          text = await callGroq(prompt, apiKey.trim());
          usedAI = true;
        } catch (groqErr) {
          console.warn("Groq failed, using offline brief:", groqErr);
          text = buildFallbackBrief(briefData, dateStr);
        }
      } else {
        text = buildFallbackBrief(briefData, dateStr);
      }

      setRawBrief(text);
      setParsedSections(parseBrief(text));
      toast({
        title: "Brief ready",
        description: usedAI ? "Generated by Groq AI (Llama 70B)" : "Generated from live threat data",
      });
    } catch (err) {
      console.error("Brief generation error:", err);
      // Last-resort: always show something useful
      if (briefData) {
        const fallback = buildFallbackBrief(briefData, dateStr);
        setRawBrief(fallback);
        setParsedSections(parseBrief(fallback));
        toast({ title: "Brief ready", description: "Generated from live threat data (AI unavailable)" });
      } else {
        toast({ title: "Failed to generate brief", description: "No threat data loaded yet — refresh and try again", variant: "destructive" });
      }
    } finally {
      setGenerating(false);
    }
  }

  // ── Export PDF ─────────────────────────────────────────────────────────────

  function exportPDF() {
    const style = document.createElement("style");
    style.id = "ciso-print-style";
    style.textContent = `
      @media print {
        body > * { display: none !important; }
        #ciso-brief-print { display: block !important; }
        #ciso-brief-print { color: #000 !important; background: #fff !important; }
        .no-print { display: none !important; }
      }
    `;
    document.head.appendChild(style);
    window.print();
    setTimeout(() => {
      const el = document.getElementById("ciso-print-style");
      if (el) el.remove();
    }, 1000);
  }

  // ── Email Brief ────────────────────────────────────────────────────────────

  async function emailBrief() {
    if (!briefData || !rawBrief) {
      toast({
        title: "No brief to send",
        description: "Please generate a brief first.",
        variant: "destructive",
      });
      return;
    }

    setEmailing(true);
    try {
      const topCritical = briefData.recentCritical[0];
      const { error } = await supabase.functions.invoke("send-alerts", {
        body: {
          manual_item: topCritical
            ? {
                title: topCritical.title,
                severity: topCritical.severity,
                category: topCritical.category,
                source_name: topCritical.source_name,
                excerpt: topCritical.excerpt,
                published_at: topCritical.published_at,
              }
            : {
                title: `Leadership Updates — ${dateStr}`,
                severity: "high",
                category: "Executive Report",
                source_name: "ThreatLens Platform",
                excerpt: `Daily threat summary: ${briefData.critical} critical, ${briefData.high} high threats detected.`,
                published_at: new Date().toISOString(),
              },
          manual_summary: rawBrief,
        },
      });

      if (error) throw error;

      toast({ title: "Brief emailed", description: "The executive brief has been sent." });
    } catch (err) {
      console.error("Email error:", err);
      toast({
        title: "Email failed",
        description: String(err),
        variant: "destructive",
      });
    } finally {
      setEmailing(false);
    }
  }

  // ── Derived values ─────────────────────────────────────────────────────────

  const risk = briefData ? riskLevel(briefData.critical) : "LOW";

  const severityChartData = briefData
    ? [
        { name: "Critical", value: briefData.critical, color: SEVERITY_COLORS.critical },
        { name: "High", value: briefData.high, color: SEVERITY_COLORS.high },
        { name: "Medium", value: briefData.medium, color: SEVERITY_COLORS.medium },
        { name: "Low", value: briefData.low, color: SEVERITY_COLORS.low },
      ]
    : [];

  const totalCat = briefData?.topCategories.reduce((s, c) => s + c.count, 0) ?? 1;

  // ── Render ─────────────────────────────────────────────────────────────────

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 p-6 space-y-6" id="ciso-brief-print">
      {/* ── Header ── */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div className="flex items-center gap-3">
          <div className="p-2 bg-blue-600/20 rounded-lg border border-blue-500/30">
            <Shield className="w-6 h-6 text-blue-400" />
          </div>
          <div>
            <h1 className="text-2xl font-bold text-white tracking-tight">Leadership Updates</h1>
            <p className="text-slate-400 text-sm flex items-center gap-1 mt-0.5">
              <Clock className="w-3.5 h-3.5" />
              {dateStr}
            </p>
          </div>
        </div>

        <div className="flex flex-wrap items-center gap-2 no-print">
          <Button
            variant="outline"
            size="sm"
            className="border-slate-700 text-slate-300 hover:text-white"
            onClick={fetchData}
            disabled={loading}
          >
            <RefreshCw className={`w-4 h-4 mr-2 ${loading ? "animate-spin" : ""}`} />
            Refresh Data
          </Button>

          <Button
            size="sm"
            className="bg-blue-600 hover:bg-blue-700 text-white"
            onClick={generateBrief}
            disabled={generating || loading || !briefData}
          >
            <Zap className={`w-4 h-4 mr-2 ${generating ? "animate-pulse" : ""}`} />
            {generating ? "Generating…" : "Generate Today's Brief"}
          </Button>

          <Button
            variant="outline"
            size="sm"
            className="border-slate-700 text-slate-300 hover:text-white"
            onClick={exportPDF}
            disabled={parsedSections.length === 0}
          >
            <Download className="w-4 h-4 mr-2" />
            Export PDF
          </Button>

          <Button
            variant="outline"
            size="sm"
            className="border-slate-700 text-slate-300 hover:text-white"
            onClick={emailBrief}
            disabled={emailing || parsedSections.length === 0}
          >
            <Mail className={`w-4 h-4 mr-2 ${emailing ? "animate-pulse" : ""}`} />
            {emailing ? "Sending…" : "Email Brief"}
          </Button>
        </div>
      </div>

      {/* ── KPI Row ── */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
        {/* Total Today */}
        <Card className="bg-slate-900 border-slate-700/50">
          <CardContent className="pt-5">
            <div className="flex items-start justify-between">
              <div>
                <p className="text-slate-400 text-xs font-medium uppercase tracking-wider">
                  Threats Today
                </p>
                <p className="text-3xl font-bold text-white mt-1">
                  {loading ? "—" : (briefData?.totalToday ?? 0)}
                </p>
              </div>
              <div className="p-2 bg-blue-600/15 rounded-lg border border-blue-500/20">
                <TrendingUp className="w-5 h-5 text-blue-400" />
              </div>
            </div>
            <p className="text-slate-500 text-xs mt-2">New items since midnight</p>
          </CardContent>
        </Card>

        {/* Critical */}
        <Card className="bg-slate-900 border-red-500/20">
          <CardContent className="pt-5">
            <div className="flex items-start justify-between">
              <div>
                <p className="text-red-400 text-xs font-medium uppercase tracking-wider">
                  Critical Alerts
                </p>
                <p className="text-3xl font-bold text-red-400 mt-1">
                  {loading ? "—" : (briefData?.critical ?? 0)}
                </p>
              </div>
              <div className="p-2 bg-red-600/15 rounded-lg border border-red-500/20">
                <AlertOctagon className="w-5 h-5 text-red-400" />
              </div>
            </div>
            <p className="text-slate-500 text-xs mt-2">Immediate attention required</p>
          </CardContent>
        </Card>

        {/* High */}
        <Card className="bg-slate-900 border-orange-500/20">
          <CardContent className="pt-5">
            <div className="flex items-start justify-between">
              <div>
                <p className="text-orange-400 text-xs font-medium uppercase tracking-wider">
                  High Alerts
                </p>
                <p className="text-3xl font-bold text-orange-400 mt-1">
                  {loading ? "—" : (briefData?.high ?? 0)}
                </p>
              </div>
              <div className="p-2 bg-orange-600/15 rounded-lg border border-orange-500/20">
                <AlertTriangle className="w-5 h-5 text-orange-400" />
              </div>
            </div>
            <p className="text-slate-500 text-xs mt-2">Elevated priority threats</p>
          </CardContent>
        </Card>

        {/* Overall Risk */}
        <Card className="bg-slate-900 border-slate-700/50">
          <CardContent className="pt-5">
            <div className="flex items-start justify-between">
              <div>
                <p className="text-slate-400 text-xs font-medium uppercase tracking-wider">
                  Overall Risk
                </p>
                <div className="mt-2">
                  <span
                    className={`inline-block px-3 py-1 rounded-full text-sm font-bold ${riskBadgeColor(risk)}`}
                  >
                    {loading ? "—" : risk}
                  </span>
                </div>
              </div>
              <div className="p-2 bg-slate-700/40 rounded-lg border border-slate-600/30">
                <Shield className="w-5 h-5 text-slate-300" />
              </div>
            </div>
            <p className="text-slate-500 text-xs mt-2">Based on critical threat count</p>
          </CardContent>
        </Card>
      </div>

      {/* ── Main 2-Column Layout ── */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Left: AI Brief (2/3) */}
        <div className="lg:col-span-2 space-y-4">
          <Card className="bg-slate-900 border-slate-700/50">
            <CardHeader className="pb-3">
              <CardTitle className="text-white flex items-center gap-2 text-base">
                <FileText className="w-5 h-5 text-blue-400" />
                AI Leadership Brief
                {parsedSections.length > 0 && (
                  <Badge className="ml-2 bg-green-600/20 text-green-400 border border-green-500/30 text-xs">
                    <Check className="w-3 h-3 mr-1" />
                    Generated
                  </Badge>
                )}
              </CardTitle>
            </CardHeader>
            <CardContent>
              {parsedSections.length === 0 ? (
                <div className="flex flex-col items-center justify-center py-16 text-center">
                  <div className="p-4 bg-slate-800/60 rounded-full mb-4">
                    <Zap className="w-8 h-8 text-blue-400" />
                  </div>
                  <h3 className="text-slate-200 font-semibold text-lg mb-2">
                    Your Brief Awaits
                  </h3>
                  <p className="text-slate-400 text-sm max-w-xs mb-6">
                    Click "Generate Today's Brief" to create an AI-powered executive summary
                    tailored for board-level review.
                  </p>
                  <Button
                    className="bg-blue-600 hover:bg-blue-700 text-white no-print"
                    onClick={generateBrief}
                    disabled={generating || loading || !briefData}
                  >
                    <Zap className="w-4 h-4 mr-2" />
                    {generating ? "Generating…" : "Generate Today's Brief"}
                  </Button>
                </div>
              ) : (
                <div className="space-y-4">
                  {parsedSections.map((section, idx) => {
                    const style = SECTION_STYLES[section.header] ?? DEFAULT_SECTION_STYLE;
                    return (
                      <div
                        key={idx}
                        className={`rounded-lg border ${style.border} bg-slate-800/40 p-4`}
                      >
                        <div
                          className={`flex items-center gap-2 font-semibold text-sm uppercase tracking-wider mb-2 ${style.headerColor}`}
                        >
                          {style.icon}
                          {section.header}
                        </div>
                        <div className="text-slate-300 text-sm leading-relaxed whitespace-pre-wrap">
                          {section.body}
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
            </CardContent>
          </Card>
        </div>

        {/* Right: Charts (1/3) */}
        <div className="space-y-4">
          {/* Severity Distribution */}
          <Card className="bg-slate-900 border-slate-700/50">
            <CardHeader className="pb-2">
              <CardTitle className="text-white text-sm flex items-center gap-2">
                <TrendingUp className="w-4 h-4 text-purple-400" />
                Severity Distribution
              </CardTitle>
            </CardHeader>
            <CardContent>
              {loading ? (
                <div className="h-40 flex items-center justify-center text-slate-500 text-sm">
                  Loading…
                </div>
              ) : (
                <ResponsiveContainer width="100%" height={160}>
                  <BarChart data={severityChartData} margin={{ top: 4, right: 4, left: -20, bottom: 0 }}>
                    <XAxis
                      dataKey="name"
                      tick={{ fill: "#94a3b8", fontSize: 11 }}
                      axisLine={false}
                      tickLine={false}
                    />
                    <YAxis
                      tick={{ fill: "#94a3b8", fontSize: 11 }}
                      axisLine={false}
                      tickLine={false}
                    />
                    <Tooltip
                      contentStyle={{
                        background: "#1e293b",
                        border: "1px solid #334155",
                        borderRadius: 8,
                        color: "#f1f5f9",
                        fontSize: 12,
                      }}
                      cursor={{ fill: "rgba(255,255,255,0.05)" }}
                    />
                    <Bar dataKey="value" radius={[4, 4, 0, 0]}>
                      {severityChartData.map((entry, i) => (
                        <Cell key={i} fill={entry.color} />
                      ))}
                    </Bar>
                  </BarChart>
                </ResponsiveContainer>
              )}
            </CardContent>
          </Card>

          {/* Top Threat Categories */}
          <Card className="bg-slate-900 border-slate-700/50">
            <CardHeader className="pb-2">
              <CardTitle className="text-white text-sm flex items-center gap-2">
                <Globe className="w-4 h-4 text-cyan-400" />
                Top Threat Categories
              </CardTitle>
            </CardHeader>
            <CardContent>
              {loading ? (
                <div className="text-slate-500 text-sm text-center py-4">Loading…</div>
              ) : briefData?.topCategories.length === 0 ? (
                <div className="text-slate-500 text-sm text-center py-4">No data today</div>
              ) : (
                <div className="space-y-3">
                  {briefData?.topCategories.map((cat, i) => {
                    const pct = Math.round((cat.count / Math.max(totalCat, 1)) * 100);
                    return (
                      <div key={i}>
                        <div className="flex justify-between text-xs text-slate-400 mb-1">
                          <span className="truncate max-w-[150px]">{cat.name}</span>
                          <span className="text-slate-300 font-medium ml-2">
                            {cat.count} ({pct}%)
                          </span>
                        </div>
                        <div className="h-1.5 rounded-full bg-slate-700 overflow-hidden">
                          <div
                            className="h-full rounded-full bg-gradient-to-r from-blue-500 to-cyan-500 transition-all duration-500"
                            style={{ width: `${pct}%` }}
                          />
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
            </CardContent>
          </Card>
        </div>
      </div>

      {/* ── Bottom: Today's Threats Table ── */}
      <Card className="bg-slate-900 border-slate-700/50">
        <CardHeader className="pb-3">
          <CardTitle className="text-white flex items-center gap-2 text-base">
            <Eye className="w-5 h-5 text-slate-400" />
            Today's Top Threats
            <span className="text-slate-500 text-sm font-normal ml-1">
              (latest {briefData?.latestItems.length ?? 0})
            </span>
          </CardTitle>
        </CardHeader>
        <CardContent className="p-0">
          {loading ? (
            <div className="text-slate-500 text-sm text-center py-10">Loading threat data…</div>
          ) : !briefData || briefData.latestItems.length === 0 ? (
            <div className="text-slate-500 text-sm text-center py-10">
              No threats detected today.
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="border-b border-slate-700/50">
                    <th className="text-left text-slate-400 text-xs uppercase tracking-wider px-6 py-3 font-medium">
                      Threat Title
                    </th>
                    <th className="text-left text-slate-400 text-xs uppercase tracking-wider px-4 py-3 font-medium">
                      Severity
                    </th>
                    <th className="text-left text-slate-400 text-xs uppercase tracking-wider px-4 py-3 font-medium hidden md:table-cell">
                      Source
                    </th>
                    <th className="text-left text-slate-400 text-xs uppercase tracking-wider px-4 py-3 font-medium hidden sm:table-cell">
                      Time
                    </th>
                  </tr>
                </thead>
                <tbody>
                  {briefData.latestItems.map((item, idx) => (
                    <tr
                      key={item.id}
                      className={`border-b border-slate-800/60 hover:bg-slate-800/40 transition-colors ${
                        idx % 2 === 0 ? "bg-slate-900/40" : "bg-slate-900/10"
                      }`}
                    >
                      <td className="px-6 py-3">
                        <p className="text-slate-200 font-medium line-clamp-2 max-w-md">
                          {item.title}
                        </p>
                        {item.excerpt && (
                          <p className="text-slate-500 text-xs mt-0.5 line-clamp-1">
                            {item.excerpt}
                          </p>
                        )}
                      </td>
                      <td className="px-4 py-3">
                        <span
                          className={`inline-block px-2 py-0.5 rounded text-xs font-semibold capitalize ${severityBadgeColor(
                            item.severity
                          )}`}
                        >
                          {item.severity}
                        </span>
                      </td>
                      <td className="px-4 py-3 text-slate-400 text-xs hidden md:table-cell">
                        <div className="flex items-center gap-1">
                          <Building className="w-3 h-3 flex-shrink-0" />
                          <span className="truncate max-w-[140px]">{item.source_name}</span>
                        </div>
                      </td>
                      <td className="px-4 py-3 text-slate-500 text-xs hidden sm:table-cell">
                        <div className="flex items-center gap-1">
                          <Clock className="w-3 h-3 flex-shrink-0" />
                          {formatDate(item.published_at)}
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}
